   176	void Hints::readTables(BaseStream *str, Linearization *linearization, XRef *xref, SecurityHandler *secHdlr)
   177	{
   178	  hintsOffset = linearization->getHintsOffset();
   179	  hintsLength = linearization->getHintsLength();
   180	  hintsOffset2 = linearization->getHintsOffset2();
   181	  hintsLength2 = linearization->getHintsLength2();
   182	
   183	  Parser *parser;
   184	
   185	  int bufLength = hintsLength + hintsLength2;
   186	
   187	  std::vector<char> buf(bufLength);
   188	  char *p = &buf[0];
   189	
   190	  Stream *s = str->makeSubStream(hintsOffset, false, hintsLength, Object(objNull));
   191	  s->reset();
   192	  for (Guint i=0; i < hintsLength; i++) { *p++ = s->getChar(); }
   193	  delete s;
   194	
   195	  if (hintsOffset2 && hintsLength2) {
   196	    s = str->makeSubStream(hintsOffset2, false, hintsLength2, Object(objNull));
   197	    s->reset();
   198	    for (Guint i=0; i < hintsLength2; i++) { *p++ = s->getChar(); }
   199	    delete s;
   200	  }
   201	
   202	  MemStream *memStream = new MemStream (&buf[0], 0, bufLength, Object(objNull));
   203	
   204	  parser = new Parser(xref, new Lexer(xref, memStream), true);
   205	
   206	  int num, gen;
   207	  Object obj;
   208	  if ((obj = parser->getObj(), obj.isInt()) &&
   209	     (num = obj.getInt(), obj = parser->getObj(), obj.isInt()) &&
   210	     (gen = obj.getInt(), obj = parser->getObj(), obj.isCmd("obj")) &&
   211	     (obj = parser->getObj(false,
   212	         secHdlr ? secHdlr->getFileKey() : nullptr,
   213	         secHdlr ? secHdlr->getEncAlgorithm() : cryptRC4,
   214	         secHdlr ? secHdlr->getFileKeyLength() : 0,
   215	         num, gen, 0, true), obj.isStream())) {
   216	    Stream *hintsStream = obj.getStream();
   217	    Dict *hintsDict = obj.streamGetDict();
   218	
   219	    int sharedStreamOffset = 0;
   220	    if (hintsDict->lookupInt("S", nullptr, &sharedStreamOffset) &&
   221	        sharedStreamOffset > 0) {
   222	
   223	        hintsStream->reset();
   224	        ok = readPageOffsetTable(hintsStream);
   225	
   226	        if (ok) {
   227	          hintsStream->reset();
   228	          for (int i=0; i<sharedStreamOffset; i++) hintsStream->getChar();
   229	          ok = readSharedObjectsTable(hintsStream);
   230	        }
   231	    } else {
   232	      error(errSyntaxWarning, -1, "Invalid shared object hint table offset");
   233	    }
   234	  } else {
   235	    error(errSyntaxWarning, -1, "Failed parsing hints table object");
   236	  }
   237	
   238	  delete parser;
   239	}
