   241	bool Hints::readPageOffsetTable(Stream *str)
   242	{
   243	  if (nPages < 1) {
   244	    error(errSyntaxWarning, -1, "Invalid number of pages reading page offset hints table");
   245	    return false;
   246	  }
   247	
   248	  StreamBitReader sbr(str);
   249	
   250	  nObjectLeast = sbr.readBits(32);
   251	  if (nObjectLeast < 1) {
   252	    error(errSyntaxWarning, -1, "Invalid least number of objects reading page offset hints table");
   253	    nPages = 0;
   254	    return false;
   255	  }
   256	
   257	  objectOffsetFirst = sbr.readBits(32);
   258	  if (objectOffsetFirst >= hintsOffset) objectOffsetFirst += hintsLength;
   259	
   260	  nBitsDiffObjects = sbr.readBits(16);
   261	  if (nBitsDiffObjects > 32) {
   262	    error(errSyntaxWarning, -1, "Invalid number of bits needed to represent the difference between the greatest and least number of objects in a page");
   263	    nPages = 0;
   264	    return false;
   265	  }
   266	
   267	  pageLengthLeast = sbr.readBits(32);
   268	
   269	  nBitsDiffPageLength = sbr.readBits(16);
   270	
   271	  OffsetStreamLeast = sbr.readBits(32);
   272	
   273	  nBitsOffsetStream = sbr.readBits(16);
   274	
   275	  lengthStreamLeast = sbr.readBits(32);
   276	
   277	  nBitsLengthStream = sbr.readBits(16);
   278	
   279	  nBitsNumShared = sbr.readBits(16);
   280	
   281	  nBitsShared = sbr.readBits(16);
   282	
   283	  nBitsNumerator = sbr.readBits(16);
   284	
   285	  denominator = sbr.readBits(16);
   286	
   287	  for (int i = 0; i < nPages && !sbr.atEOF(); i++) {
   288	    nObjects[i] = nObjectLeast + sbr.readBits(nBitsDiffObjects);
   289	  }
   290	  if (sbr.atEOF())
   291	    return false;
   292	
   293	  nObjects[0] = 0;
   294	  xRefOffset[0] = mainXRefEntriesOffset + 20;
   295	  for (int i=1; i<nPages; i++) {
   296	    xRefOffset[i] = xRefOffset[i-1] + 20*nObjects[i-1];
   297	  }
   298	
   299	  pageObjectNum[0] = 1;
   300	  for (int i=1; i<nPages; i++) {
   301	    pageObjectNum[i] = pageObjectNum[i-1] + nObjects[i-1];
   302	  }
   303	  pageObjectNum[0] = pageObjectFirst;
   304	
   305	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   306	  for (int i = 0; i < nPages && !sbr.atEOF(); i++) {
   307	    pageLength[i] = pageLengthLeast + sbr.readBits(nBitsDiffPageLength);
   308	  }
   309	  if (sbr.atEOF())
   310	    return false;
   311	
   312	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   313	  numSharedObject[0] = sbr.readBits(nBitsNumShared);
   314	  numSharedObject[0] = 0; // Do not trust the read value to be 0.
   315	  sharedObjectId[0] = nullptr;
   316	  for (int i = 1; i < nPages && !sbr.atEOF(); i++) {
   317	    numSharedObject[i] = sbr.readBits(nBitsNumShared);
   318	    if (numSharedObject[i] >= INT_MAX / (int)sizeof(Guint)) {
   319	       error(errSyntaxWarning, -1, "Invalid number of shared objects");
   320	       numSharedObject[i] = 0;
   321	       return false;
   322	    }
   323	    sharedObjectId[i] = (Guint *) gmallocn_checkoverflow(numSharedObject[i], sizeof(Guint));
   324	    if (numSharedObject[i] && !sharedObjectId[i]) {
   325	       error(errSyntaxWarning, -1, "Failed to allocate memory for shared object IDs");
   326	       numSharedObject[i] = 0;
   327	       return false;
   328	    }
   329	  }
   330	  if (sbr.atEOF())
   331	    return false;
   332	
   333	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   334	  for (int i=1; i<nPages; i++) {
   335	    for (Guint j = 0; j < numSharedObject[i] && !sbr.atEOF(); j++) {
   336	      sharedObjectId[i][j] = sbr.readBits(nBitsShared);
   337	    }
   338	  }
   339	
   340	  pageOffset[0] = pageOffsetFirst;
   341	  // find pageOffsets.
   342	  for (int i=1; i<nPages; i++) {
   343	    pageOffset[i] = pageOffset[i-1] + pageLength[i-1];
   344	  }
   345	
   346	  return !sbr.atEOF();
   347	}
