   349	bool Hints::readSharedObjectsTable(Stream *str)
   350	{
   351	  StreamBitReader sbr(str);
   352	
   353	  const Guint firstSharedObjectNumber = sbr.readBits(32);
   354	
   355	  const Guint firstSharedObjectOffset = sbr.readBits(32) + hintsLength;
   356	
   357	  const Guint nSharedGroupsFirst = sbr.readBits(32);
   358	
   359	  const Guint nSharedGroups = sbr.readBits(32);
   360	
   361	  const Guint nBitsNumObjects = sbr.readBits(16);
   362	
   363	  const Guint groupLengthLeast = sbr.readBits(32);
   364	
   365	  const Guint nBitsDiffGroupLength = sbr.readBits(16);
   366	
   367	  if ((!nSharedGroups) || (nSharedGroups >= INT_MAX / (int)sizeof(Guint))) {
   368	     error(errSyntaxWarning, -1, "Invalid number of shared object groups");
   369	     return false;
   370	  }
   371	  if ((!nSharedGroupsFirst) || (nSharedGroupsFirst > nSharedGroups)) {
   372	     error(errSyntaxWarning, -1, "Invalid number of first page shared object groups");
   373	     return false;
   374	  }
   375	  if (nBitsNumObjects > 32 || nBitsDiffGroupLength > 32) {
   376	     error(errSyntaxWarning, -1, "Invalid shared object groups bit length");
   377	     return false;
   378	  }
   379	
   380	  groupLength = (Guint *) gmallocn_checkoverflow(nSharedGroups, sizeof(Guint));
   381	  groupOffset = (Guint *) gmallocn_checkoverflow(nSharedGroups, sizeof(Guint));
   382	  groupHasSignature = (Guint *) gmallocn_checkoverflow(nSharedGroups, sizeof(Guint));
   383	  groupNumObjects = (Guint *) gmallocn_checkoverflow(nSharedGroups, sizeof(Guint));
   384	  groupXRefOffset = (Guint *) gmallocn_checkoverflow(nSharedGroups, sizeof(Guint));
   385	  if (!groupLength || !groupOffset || !groupHasSignature ||
   386	      !groupNumObjects || !groupXRefOffset) {
   387	     error(errSyntaxWarning, -1, "Failed to allocate memory for shared object groups");
   388	     return false;
   389	  }
   390	
   391	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   392	  for (Guint i = 0; i < nSharedGroups && !sbr.atEOF(); i++) {
   393	    groupLength[i] = groupLengthLeast + sbr.readBits(nBitsDiffGroupLength);
   394	  }
   395	  if (sbr.atEOF())
   396	    return false;
   397	
   398	  groupOffset[0] = objectOffsetFirst;
   399	  for (Guint i=1; i<nSharedGroupsFirst; i++) {
   400	    groupOffset[i] = groupOffset[i-1] + groupLength[i-1];
   401	  }
   402	  if (nSharedGroups > nSharedGroupsFirst ) {
   403	    groupOffset[nSharedGroupsFirst] = firstSharedObjectOffset;
   404	    for (Guint i=nSharedGroupsFirst+1; i<nSharedGroups; i++) {
   405	      groupOffset[i] = groupOffset[i-1] + groupLength[i-1];
   406	    }
   407	  }
   408	
   409	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   410	  for (Guint i = 0; i < nSharedGroups && !sbr.atEOF(); i++) {
   411	    groupHasSignature[i] = sbr.readBits(1);
   412	  }
   413	  if (sbr.atEOF())
   414	    return false;
   415	
   416	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   417	  for (Guint i = 0; i < nSharedGroups && !sbr.atEOF(); i++) {
   418	    if (groupHasSignature[i]) {
   419	       sbr.readBits(128);
   420	    }
   421	  }
   422	  if (sbr.atEOF())
   423	    return false;
   424	
   425	  sbr.resetInputBits(); // reset on byte boundary. Not in specs!
   426	  for (Guint i = 0; i < nSharedGroups && !sbr.atEOF(); i++) {
   427	    groupNumObjects[i] =
   428	       nBitsNumObjects ? 1 + sbr.readBits(nBitsNumObjects) : 1;
   429	  }
   430	
   431	  for (Guint i=0; i<nSharedGroupsFirst; i++) {
   432	    groupNumObjects[i] = 0;
   433	    groupXRefOffset[i] = 0;
   434	  }
   435	  if (nSharedGroups > nSharedGroupsFirst ) {
   436	    groupXRefOffset[nSharedGroupsFirst] =
   437	        mainXRefEntriesOffset + 20*firstSharedObjectNumber;
   438	    for (Guint i=nSharedGroupsFirst+1; i<nSharedGroups; i++) {
   439	      groupXRefOffset[i] = groupXRefOffset[i-1] + 20*groupNumObjects[i-1];
   440	    }
   441	  }
   442	
   443	  return !sbr.atEOF();
   444	}
