   463	std::vector<ByteRange>* Hints::getPageRanges(int page)
   464	{
   465	  if ((page < 1) || (page > nPages)) return nullptr;
   466	
   467	  int idx;
   468	  if (page-1 > pageFirst)
   469	     idx = page-1;
   470	  else if (page-1 < pageFirst)
   471	     idx = page;
   472	  else
   473	     idx = 0;
   474	
   475	  ByteRange pageRange;
   476	  std::vector<ByteRange> *v = new std::vector<ByteRange>;
   477	
   478	  pageRange.offset = pageOffset[idx];
   479	  pageRange.length = pageLength[idx];
   480	  v->push_back(pageRange);
   481	
   482	  pageRange.offset = xRefOffset[idx];
   483	  pageRange.length = 20*nObjects[idx];
   484	  v->push_back(pageRange);
   485	
   486	  for (Guint j=0; j<numSharedObject[idx]; j++) {
   487	     Guint k = sharedObjectId[idx][j];
   488	
   489	     pageRange.offset = groupOffset[k];
   490	     pageRange.length = groupLength[k];
   491	     v->push_back(pageRange);
   492	
   493	     pageRange.offset = groupXRefOffset[k];
   494	     pageRange.length = 20*groupNumObjects[k];
   495	     v->push_back(pageRange);
   496	  }
   497	
   498	  return v;
   499	}
